import{_ as a,o as n,c as e,a6 as p}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"proxy 反向代理","description":"proxy_pass 带不带 URI 的本质区别、默认 Host 的坑、缓冲与超时、proxy_next_upstream 的重试语义。","frontmatter":{"title":"proxy 反向代理","description":"proxy_pass 带不带 URI 的本质区别、默认 Host 的坑、缓冲与超时、proxy_next_upstream 的重试语义。","source":"https://daiw.org/manual/nginx/proxy"},"headers":[],"relativePath":"manual/tools/nginx/proxy.md","filePath":"manual/tools/nginx/proxy.md"}'),t={name:"manual/tools/nginx/proxy.md"};function r(o,s,i,l,d,c){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="proxy-反向代理" tabindex="-1">proxy 反向代理 <a class="header-anchor" href="#proxy-反向代理" aria-label="Permalink to &quot;proxy 反向代理&quot;">​</a></h1><h2 id="proxy-pass-的斜杠之争" tabindex="-1">proxy_pass 的斜杠之争 <a class="header-anchor" href="#proxy-pass-的斜杠之争" aria-label="Permalink to &quot;proxy\\_pass 的斜杠之争&quot;">​</a></h2><p>这是 nginx 配置里<strong>最著名</strong>的一个坑。官方规则原文：</p><blockquote><p>If the <code>proxy_pass</code> directive is specified <strong>with a URI</strong>, then when a request is passed to the server, the part of a <strong>normalized request URI matching the location is replaced</strong> by a URI specified in the directive.</p></blockquote><p>一句话：<strong>带 URI 就替换，不带 URI 就透传</strong>。</p><h3 id="带-uri-含末尾-→-替换" tabindex="-1">带 URI（含末尾 <code>/</code>）→ 替换 <a class="header-anchor" href="#带-uri-含末尾-→-替换" aria-label="Permalink to &quot;带 URI（含末尾 \`/\`）→ 替换&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /name/ {</span></span>
<span class="line"><span>    proxy_pass http://127.0.0.1/remote/;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 /name/test  →  上游收到 /remote/test</span></span>
<span class="line"><span>     ^^^^^^ 被替换成 /remote/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="不带-uri-→-透传" tabindex="-1">不带 URI → 透传 <a class="header-anchor" href="#不带-uri-→-透传" aria-label="Permalink to &quot;不带 URI → 透传&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /some/path/ {</span></span>
<span class="line"><span>    proxy_pass http://127.0.0.1;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求 /some/path/test  →  上游收到 /some/path/test</span></span>
<span class="line"><span>     完整 URI 原样传过去</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>判断标准是「proxy_pass 里主机后面有没有路径」，不是「有没有斜杠」这么简单：</strong></p><table tabindex="0"><thead><tr><th>写法</th><th>是否带 URI</th><th>效果</th></tr></thead><tbody><tr><td><code>proxy_pass http://backend;</code></td><td><strong>否</strong></td><td>透传完整 URI</td></tr><tr><td><code>proxy_pass http://backend/;</code></td><td><strong>是</strong>（URI 是 <code>/</code>）</td><td><code>/name/test</code> → <code>/test</code></td></tr><tr><td><code>proxy_pass http://backend/api/;</code></td><td>是</td><td><code>/name/test</code> → <code>/api/test</code></td></tr></tbody></table><p><strong><code>http://backend;</code> 与 <code>http://backend/;</code> 行为完全不同</strong>——后者那个孤零零的 <code>/</code> 就是一个 URI，会把 location 前缀吃掉。这一个字符的差别造成过无数 404。</p><h3 id="三种不能带-uri-的情况" tabindex="-1">三种不能带 URI 的情况 <a class="header-anchor" href="#三种不能带-uri-的情况" aria-label="Permalink to &quot;三种不能带 URI 的情况&quot;">​</a></h3><p>官方明确列出：</p><ul><li><strong>正则 location</strong> 与<strong>命名 location</strong>——必须用不带 URI 的形式。</li><li><strong><code>rewrite ... break</code> 之后</strong>——指令里的 URI 被忽略，传的是改写后的完整 URI。</li><li><strong>proxy_pass 里含变量时</strong>——指定的 URI 原样传递，替换原 URI。</li></ul><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 正则 location：不能带 URI</span></span>
<span class="line"><span>location ~ ^/api/(.*)$ {</span></span>
<span class="line"><span>    proxy_pass http://backend;      # ✅</span></span>
<span class="line"><span>    # proxy_pass http://backend/$1; ← 含变量，行为又不同</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>含变量时行为特殊，且<strong>变量形式不会做上游组解析</strong>（后面 upstream 章会讲），慎用。</p><h2 id="host-头默认值的坑" tabindex="-1">Host 头默认值的坑 <a class="header-anchor" href="#host-头默认值的坑" aria-label="Permalink to &quot;Host 头默认值的坑&quot;">​</a></h2><p>官方给的默认：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_set_header Host       $proxy_host;</span></span>
<span class="line"><span>proxy_set_header Connection close;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>默认传给上游的 <code>Host</code> 是 <code>$proxy_host</code></strong>——即 <code>proxy_pass</code> 里写的那个主机名，<strong>不是客户端请求的 Host</strong>。</p><p>后果：上游若按 <a href="/Front2Full/manual/tools/nginx/request-processing">Host 做虚拟主机路由</a>，会全部落到默认站点；应用生成的绝对 URL 也会带错域名。</p><p><strong>所以几乎所有反代配置的第一行都是</strong>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_set_header Host $host;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>HTTP/2 与 gRPC 场景下，<code>:authority</code> 伪头默认同样用 <code>$proxy_host</code>；若显式设置了 <code>proxy_set_header Host</code> 或 <code>grpc_set_header Host</code>，则将其值写入 <code>:authority</code>（1.31.4 起不再同时附带冗余的 <code>Host</code> 头）。见 <a href="https://daiw.org/manual/http2-3/h2-pseudo-headers" target="_blank" rel="noreferrer">HTTP/2 伪头</a>。</p><h2 id="标准转发头四件套" tabindex="-1">标准转发头四件套 <a class="header-anchor" href="#标准转发头四件套" aria-label="Permalink to &quot;标准转发头四件套&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_set_header Host              $host;</span></span>
<span class="line"><span>proxy_set_header X-Real-IP         $remote_addr;</span></span>
<span class="line"><span>proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;</span></span>
<span class="line"><span>proxy_set_header X-Forwarded-Proto $scheme;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><code>$proxy_add_x_forwarded_for</code> = <strong>原有 <code>X-Forwarded-For</code> 值 + <code>,</code> + <code>$remote_addr</code></strong>，实现<a href="https://daiw.org/manual/http11/proxy-fields" target="_blank" rel="noreferrer">逐跳追加</a>。</p><p><strong>边缘节点应该覆写而不是追加。</strong> 最外层 nginx 直接面对公网时，客户端可以自己伪造 <code>X-Forwarded-For</code>，追加会把伪造值留在最左边。边缘应写：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_set_header X-Forwarded-For $remote_addr;   # 覆写，丢弃客户端自带的</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>只有在<strong>内层</strong>（前面确定有可信代理）才用 <code>$proxy_add_x_forwarded_for</code>。详见 <a href="https://daiw.org/manual/http11/proxy-fields" target="_blank" rel="noreferrer">HTTP 代理字段的安全模型</a>。</p><p>别忘了<a href="/Front2Full/manual/tools/nginx/contexts">数组型继承</a>：任何一个内层 location 写了 <code>proxy_set_header</code>，这四条全失效。</p><h2 id="proxy-http-version" tabindex="-1">proxy_http_version <a class="header-anchor" href="#proxy-http-version" aria-label="Permalink to &quot;proxy\\_http\\_version&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    proxy_http_version 1.0 | 1.1;</span></span>
<span class="line"><span>默认:    proxy_http_version 1.1;    ← 1.29.7 起</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>默认值在 1.29.7 改了</strong>：原先是 <code>1.0</code>，现在是 <code>1.1</code>。</p><p>网上几乎所有教程都会告诉你「用 upstream keepalive 必须手动写 <code>proxy_http_version 1.1;</code>」——那是针对旧默认值的建议。新版本已经不必，但<strong>显式写上仍然无害</strong>，且对旧版本部署是必要的。</p><p>配合 <a href="/Front2Full/manual/tools/nginx/upstream">upstream keepalive</a> 时还需要清掉 <code>Connection</code> 头：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_http_version 1.1;</span></span>
<span class="line"><span>proxy_set_header   Connection &quot;&quot;;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>因为默认会发 <code>Connection: close</code>，与长连接冲突。</p><h2 id="proxy-buffering" tabindex="-1">proxy_buffering <a class="header-anchor" href="#proxy-buffering" aria-label="Permalink to &quot;proxy\\_buffering&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    proxy_buffering on | off;</span></span>
<span class="line"><span>默认:    proxy_buffering on;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>状态</th><th>行为</th></tr></thead><tbody><tr><td><code>on</code>（默认）</td><td>nginx <strong>先把上游响应完整读进缓冲</strong>，再发给客户端</td></tr><tr><td><code>off</code></td><td>收到多少<strong>同步转发</strong>多少</td></tr></tbody></table><p>缓冲的价值：<strong>快速释放上游连接</strong>。慢客户端下载时，上游不必陪着等——nginx 已经把数据收下来了。这对后端是宝贵的保护。</p><p>缓冲区配置：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_buffer_size   4k;      # 存响应头的那块（默认 4k|8k）</span></span>
<span class="line"><span>proxy_buffers       8 4k;    # 存响应体（默认 8 个 4k|8k）</span></span>
<span class="line"><span>proxy_busy_buffers_size 8k;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>超出缓冲的部分写<strong>临时文件</strong>（<code>proxy_max_temp_file_size</code>、<code>proxy_temp_file_write_size</code> 控制）。</p><p><strong>什么时候要关掉</strong>：SSE、流式响应、长轮询、大文件实时转发——这些场景缓冲会让数据卡在 nginx 里不下发。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /events {</span></span>
<span class="line"><span>    proxy_pass       http://backend;</span></span>
<span class="line"><span>    proxy_buffering  off;</span></span>
<span class="line"><span>    proxy_cache      off;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>上游也可以用响应头 <code>X-Accel-Buffering: no</code> 单次关闭缓冲，无需改 nginx 配置。</p><h2 id="超时三兄弟" tabindex="-1">超时三兄弟 <a class="header-anchor" href="#超时三兄弟" aria-label="Permalink to &quot;超时三兄弟&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>默认</th><th>含义</th></tr></thead><tbody><tr><td><code>proxy_connect_timeout</code></td><td><strong>60s</strong></td><td>与上游<strong>建立连接</strong></td></tr><tr><td><code>proxy_send_timeout</code></td><td><strong>60s</strong></td><td>两次<strong>写</strong>操作之间</td></tr><tr><td><code>proxy_read_timeout</code></td><td><strong>60s</strong></td><td>两次<strong>读</strong>操作之间</td></tr></tbody></table><p><strong><code>proxy_read_timeout</code> 不是「响应总时长上限」</strong>，而是「两次读之间的最大间隔」。上游只要持续有数据流出，跑一小时也不会超时；反之上游思考 61 秒再吐第一个字节就会 <code>504</code>。</p><p>官方另有一条限制：<code>proxy_connect_timeout</code> 通常<strong>不能超过 75 秒</strong>（受系统 TCP 连接超时约束）。</p><p>慢接口（大报表、AI 推理）需要调大 <code>proxy_read_timeout</code>：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>location /slow-api/ {</span></span>
<span class="line"><span>    proxy_pass         http://backend;</span></span>
<span class="line"><span>    proxy_read_timeout 300s;</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h2 id="proxy-next-upstream" tabindex="-1">proxy_next_upstream <a class="header-anchor" href="#proxy-next-upstream" aria-label="Permalink to &quot;proxy\\_next\\_upstream&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>语法:    proxy_next_upstream error | timeout | invalid_header |</span></span>
<span class="line"><span>                             http_500 | http_502 | http_503 | http_504 |</span></span>
<span class="line"><span>                             http_403 | http_404 | http_429 |</span></span>
<span class="line"><span>                             non_idempotent | off ...;</span></span>
<span class="line"><span>默认:    proxy_next_upstream error timeout;</span></span>
<span class="line"><span>上下文:  http, server, location</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p><strong>默认只在 <code>error</code> 与 <code>timeout</code> 时换下一台</strong>。500/502/503 默认<strong>不重试</strong>——想要就显式加：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_next_upstream error timeout http_502 http_503 http_504;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>三条重要语义：</p><p><strong>一、<code>http_403</code> / <code>http_404</code> 永不算失败尝试。</strong> 即使列出来触发换机，也不会计入该上游的失败次数（不影响 <code>max_fails</code>）。</p><p><strong>二、<code>non_idempotent</code>（1.9.13+）才会重试 POST。</strong> 默认<strong>不重试非幂等方法</strong>——这与 <a href="https://daiw.org/manual/http11/methods" target="_blank" rel="noreferrer">HTTP 的幂等性语义</a>一致。加上它意味着你接受重复提交的风险，必须有幂等键兜底。</p><p><strong>三、已经开始给客户端发数据就不能重试。</strong> 官方原话：request can only be retried if <strong>nothing sent to client yet</strong>。</p><p>限制重试规模：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>proxy_next_upstream_tries   3;    # 默认 0 = 不限</span></span>
<span class="line"><span>proxy_next_upstream_timeout 10s;  # 默认 0 = 不限</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p><strong>默认不限次数</strong>意味着上游全挂时会把所有机器试一遍——生产建议设个上限。</p><h2 id="上游相关变量" tabindex="-1">上游相关变量 <a class="header-anchor" href="#上游相关变量" aria-label="Permalink to &quot;上游相关变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>变量</th><th>含义</th></tr></thead><tbody><tr><td><code>$upstream_addr</code></td><td>实际连的上游地址（重试过会是逗号/冒号分隔的列表）</td></tr><tr><td><code>$upstream_status</code></td><td>上游返回的状态码</td></tr><tr><td><code>$upstream_response_time</code></td><td><strong>上游</strong>响应耗时</td></tr><tr><td><code>$upstream_connect_time</code></td><td>建连耗时</td></tr><tr><td><code>$upstream_cache_status</code></td><td>缓存命中状态，见<a href="/Front2Full/manual/tools/nginx/caching">缓存章</a></td></tr><tr><td><code>$upstream_http_名字</code></td><td>上游响应头</td></tr></tbody></table><p>把它们记进<a href="/Front2Full/manual/tools/nginx/logging">日志</a>是排查性能问题的基础——<code>$request_time</code> 减去 <code>$upstream_response_time</code> 就是 nginx 自身与网络的开销。</p><h2 id="一份完整反代配置" tabindex="-1">一份完整反代配置 <a class="header-anchor" href="#一份完整反代配置" aria-label="Permalink to &quot;一份完整反代配置&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>upstream backend {</span></span>
<span class="line"><span>    server 10.0.0.1:8080;</span></span>
<span class="line"><span>    server 10.0.0.2:8080;</span></span>
<span class="line"><span>    keepalive 32;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>server {</span></span>
<span class="line"><span>    listen 443 ssl;</span></span>
<span class="line"><span>    http2  on;</span></span>
<span class="line"><span>    server_name api.example.com;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location / {</span></span>
<span class="line"><span>        proxy_pass http://backend;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        proxy_http_version 1.1;</span></span>
<span class="line"><span>        proxy_set_header   Connection &quot;&quot;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        proxy_set_header Host              $host;</span></span>
<span class="line"><span>        proxy_set_header X-Real-IP         $remote_addr;</span></span>
<span class="line"><span>        proxy_set_header X-Forwarded-For   $remote_addr;    # 边缘：覆写</span></span>
<span class="line"><span>        proxy_set_header X-Forwarded-Proto $scheme;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        proxy_connect_timeout 5s;</span></span>
<span class="line"><span>        proxy_read_timeout    60s;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        proxy_next_upstream       error timeout http_502 http_503;</span></span>
<span class="line"><span>        proxy_next_upstream_tries 2;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    location /events {</span></span>
<span class="line"><span>        proxy_pass      http://backend;</span></span>
<span class="line"><span>        proxy_buffering off;</span></span>
<span class="line"><span>        proxy_read_timeout 1h;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br></div></div><p>下一篇：<a href="/Front2Full/manual/tools/nginx/upstream">upstream 负载均衡</a>。</p>`,74)])])}const h=a(t,[["render",r]]);export{u as __pageData,h as default};
